import{_ as e,o as r,c as d,a0 as o}from"./chunks/framework.Bmhw_dvp.js";const h=JSON.parse('{"title":"The Maturity Model","description":"Component of the Agentic Development Framework documentation.","frontmatter":{"type":"Agentic Development Framework","title":"The Maturity Model","description":"Component of the Agentic Development Framework documentation.","tags":["framework","internal"],"isInternal":true},"headers":[],"relativePath":"framework/maturity-model.md","filePath":"framework/maturity-model.md"}'),n={name:"framework/maturity-model.md"};function i(a,t,s,l,c,m){return r(),d("div",null,[...t[0]||(t[0]=[o('<h2 id="_4-the-maturity-model" tabindex="-1">4. The Maturity Model <a class="header-anchor" href="#_4-the-maturity-model" aria-label="Permalink to &quot;4. The Maturity Model&quot;">​</a></h2><p>Adopt the framework incrementally. Each level builds on the previous one.</p><table tabindex="0"><thead><tr><th>Level</th><th>Name</th><th>What You Add</th><th>Key Benefit</th></tr></thead><tbody><tr><td><strong>L0</strong></td><td>Unstructured</td><td>Nothing — raw AI coding</td><td>Fast prototyping, high risk</td></tr><tr><td><strong>L1</strong></td><td>Guided</td><td>Agent rules file with coding standards and persona</td><td>Consistent code style, reduced hallucination</td></tr><tr><td><strong>L2</strong></td><td>Skilled</td><td>Skills registry with domain-specific knowledge</td><td>Agent reads the right context before acting</td></tr><tr><td><strong>L3</strong></td><td>Routed</td><td>Context routing rules with exclusion zones</td><td>Token efficiency, reduced noise</td></tr><tr><td><strong>L4</strong></td><td>Tested</td><td>Agentic TDD with E2E guardrails</td><td>Functional correctness, regression prevention</td></tr><tr><td><strong>L5</strong></td><td>Structured</td><td>Swarm Architecture (Architect → Builder → Reviewer)</td><td>Separation of concerns, adversarial review</td></tr><tr><td><strong>L6</strong></td><td>Learning</td><td>Self-updating memory with ADR harvesting</td><td>Knowledge persistence across sessions</td></tr><tr><td><strong>L7</strong></td><td>Autonomous</td><td>Closed-loop CI/CD with post-deployment monitoring</td><td>End-to-end delivery without human polling</td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Start at L1.</strong> Even a minimal agent rules file with coding standards and a persona definition will measurably improve output quality. You do not need to implement all seven pillars on day one.</p></div><hr>',5)])])}const g=e(n,[["render",i]]);export{h as __pageData,g as default};
